-- Wächter Migration 210 (nur lesen). Erwartungen: werkzeuge/m210_md5.json. funktionen = die von 210 geänderten und neuen Funktionen.
SELECT (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_ui_pfad', 'ally_ui_kennung_text', 'ally_ui_kn_talent', 'ally_ui_kn_talent_darf', 'ally_ui_kn_kampagne', 'ally_ui_kn_kampagne_darf', 'ally_ui_kn_briefing', 'ally_ui_kn_briefing_darf', 'ally_ui_kn_ergebnis', 'ally_ui_kn_ergebnis_bereich', 'ally_ui_kn_ergebnis_darf', 'ally_ui_kn_person', 'ally_ui_kn_person_darf', 'ally_ui_kn_ordner', 'ally_ui_kn_ordner_darf', 'ally_ui_kn_termin', 'ally_ui_kn_termin_darf', 'ally_ui_kn_benachrichtigung', 'ally_ui_kn_benachrichtigung_bereich', 'ally_ui_kn_benachrichtigung_darf', 'ally_ui_kennung_person', 'ally_ui_kennung', 'ally_ui_kennung_person_teil', 'ally_ui_kennung_personen', 'ally_ui_kennung_fuer', 'ally_ui_kennung_pflegen', 'ally_ui_kennung_ausloeser', 'ally_ui_pfad_bauen', 'ally_ui_kennungen', 'ally_ui_kennungen_karte'])) AS funktionen;
